result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": """"Background prime-computation jobs for Flask, persisted in SQLite."""
import math
import queue
import sqlite3
import threading
import uuid

from flask import Flask, jsonify, request

TERMINAL_STATES = {"done", "failed"}
PROGRESS_EVERY = 1000  # candidates between progress writes


def get_conn(db_path):
    conn = sqlite3.connect(db_path, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    return conn


SCHEMA = """
CREATE TABLE IF NOT EXISTS jobs (
    id       TEXT PRIMARY KEY,
    n        INTEGER NOT NULL,
    status   TEXT NOT NULL DEFAULT 'queued',
    progress INTEGER NOT NULL DEFAULT 0,
    result   INTEGER,
    error    TEXT
);
"""


def nth_prime(n, on_progress=None):
    """Return the n-th prime (1-indexed). Calls on_progress(primes_found)
    every PROGRESS_EVERY candidates inspected."""
    if n < 1:
        raise ValueError("n must be >= 1")
    primes = []
    candidate = 1
    while len(primes) < n:
        candidate += 1
        limit = math.isqrt(candidate)
        is_prime = True
        for p in primes:
            if p > limit:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        if on_progress is not None and candidate % PROGRESS_EVERY == 0:
            on_progress(len(primes))
    return candidate


def create_app(db_path="jobs.db"):
    app = Flask(__name__)
    app.config["DB_PATH"] = db_path

    with get_conn(db_path) as conn:
        conn.executescript(SCHEMA)

    task_queue = queue.Queue()
    worker_lock = threading.Lock()
    worker_started = False

    def _worker():
        conn = get_conn(db_path)
        while True:
            job_id = task_queue.get()
            row = conn.execute(
                "SELECT id, n FROM jobs WHERE id = ?", (job_id,)
            ).fetchone()
            if row is None:
                continue
            n = row["n"]
            conn.execute(
                "UPDATE jobs SET status = 'running' WHERE id = ?", (job_id,)
            )
            conn.commit()

            def on_progress(primes_found, job_id=job_id, n=n):
                pct = min(int(primes_found * 100 / max(n, 1)), 99)
                try:
                    conn.execute(
                        "UPDATE jobs SET progress = ? WHERE id = ?",
                        (pct, job_id),
                    )
                    conn.commit()
                except sqlite3.Error:
                    pass

            try:
                result = nth_prime(n, on_progress)
                conn.execute(
                    "UPDATE jobs SET status = 'done', progress = 100,"
                    " result = ?, error = NULL WHERE id = ?",
                    (result, job_id),
                )
            except Exception as exc:  # noqa: BLE001 - record any failure
                conn.execute(
                    "UPDATE jobs SET status = 'failed', error = ? WHERE id = ?",
                    (f"{type(exc).__name__}: {exc}", job_id),
                )
            conn.commit()

    def _ensure_worker():
        nonlocal worker_started
        with worker_lock:
            if not worker_started:
                threading.Thread(
                    target=_worker, name="prime-worker", daemon=True
                ).start()
                worker_started = True

    @app.post("/jobs")
    def submit_job():
        data = request.get_json(silent=True) or {}
        n = data.get("n")
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            return jsonify(error="n must be a positive integer"), 400

        job_id = uuid.uuid4().hex
        with get_conn(db_path) as conn:
            conn.execute(
                "INSERT INTO jobs (id, n) VALUES (?, ?)", (job_id, n)
            )
        _ensure_worker()
        task_queue.put(job_id)
        return jsonify(id=job_id, status_url=f"/jobs/{job_id}"), 202

    @app.get("/jobs/<job_id>")
    def job_status(job_id):
        with get_conn(db_path) as conn:
            row = conn.execute(
                "SELECT id, status, progress, result, error"
                " FROM jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
        if row is None:
            return jsonify(error="job not found"), 404

        payload = {
            "id": row["id"],
            "status": row["status"],
            "progress": row["progress"],
        }
        if row["status"] == "done":
            payload["result"] = row["result"]
        elif row["status"] == "failed":
            payload["error"] = row["error"]
        return jsonify(payload)

    return app


if __name__ == "__main__":
    create_app().run(debug=False, port=5000)
