def _nth_prime_ref(n):
    """Independent sieve-based reference implementation."""
    if n < 6:
        limit = 15
    else:
        limit = int(n * (math.log(n) + math.log(math.log(n)))) + 10
    sieve = bytearray([1]) * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    count = 0
    for i in range(2, limit + 1):
        if sieve[i]:
            count += 1
            if count == n:
                return i
            sieve[i * i :: i] = bytearray(len(sieve[i * i :: i]))
    raise AssertionError("sieve upper bound too small")


def poll_until_terminal(client, job_id, timeout=30.0):
    """Poll every 0.05s until a terminal state; returns (seen_nonterminal,
    final_payload). Raises on timeout."""
    deadline = time.monotonic() + timeout
    seen_nonterminal = False
    payload = None
    while time.monotonic() < deadline:
        resp = client.get(f"/jobs/{job_id}")
        assert resp.status_code == 200
        payload = resp.get_json()
        assert payload["status"] in {"queued", "running", "done", "failed"}
        if payload["status"] in ("queued", "running"):
            seen_nonterminal = True
            assert 0 <= payload["progress"] <= 100
            if payload["status"] == "done":
                break
        else:
            assert payload["progress"] == (
                100 if payload["status"] == "done" else pytest.approx(100, abs=100)
            )
            return seen_nonterminal, payload
        time.sleep(0.05)
    raise AssertionError(f"job {job_id} did not finish within {timeout}s")


def test_submit_returns_202_with_location_fields(client):
    resp = client.post("/jobs", json={"n": 20000})
    assert resp.status_code == 202
    body = resp.get_json()
    assert set(body) == {"id", "status_url"}
    assert body["status_url"] == f"/jobs/{body['id']}"


def test_prime_job_observes_nonterminal_state_and_correct_result(client):
    resp = client.post("/jobs", json={"n": 20000})
    body = resp.get_json()

    seen_nonterminal, final = poll_until_terminal(client, body["id"])

    assert seen_nonterminal, "expected to observe queued or running state"
    assert final["status"] == "done"
    assert final["result"] == _nth_prime_ref(20000) == 224737


def test_invalid_n_rejected(client):
    for bad in (0, -5, "x", None, True):
        resp = client.post("/jobs", json={"n": bad})
        assert resp.status_code == 400
    assert client.post("/jobs", json={}).status_code == 400


def test_unknown_job_404(client):
    resp = client.get("/jobs/nonexistent")
    assert resp.status_code == 404


def test_failed_status_reported(client, monkeypatch):
    def boom(n, on_progress=None):
        raise RuntimeError("boom")

    monkeypatch.setattr("app.nth_prime", boom)
    body = client.post("/jobs", json={"n": 10}).get_json()
    _, final = poll_until_terminal(client, body["id"])
    assert final["status"] == "failed"
    assert "boom" in final["error"]
